<script setup>
import { ref, onMounted, onUnmounted } from 'vue'
import QRCode from 'qrcode'
import { isUnreadNotice } from './notice.js'
const tab = ref('shop'), token = ref(localStorage.getItem('cym-token') || ''), me = ref(null), products = ref([]), orders = ref([]), addresses = ref([]), transactions = ref([]), team = ref([]), message = ref(''), selected = ref(null), qr = ref(''), mode = ref('login'), unreadCount = ref(0)
const params = new URLSearchParams(location.hash.split('?')[1] || location.search)
const form = ref({ phone: '', username: '', password: '', invite_code: params.get('transfer_invite') || '' })
if (form.value.invite_code) { mode.value = 'register'; tab.value = 'login' }
const address = ref({ contact_name:'',contact_phone:'',province:'',city:'',district:'',detail:'' }), transfer = ref({ phone:'',amount:'',password:'' }), addressId = ref(''), variant = ref(''), busy = ref(false)
const purchaseId = ref(crypto.randomUUID()), transferId = ref(crypto.randomUUID())
async function api(path, opts = {}) { const response = await fetch('/api' + path, { ...opts, headers: { 'Content-Type': 'application/json', ...(token.value ? { Authorization: `Bearer ${token.value}` } : {}), ...opts.headers }, body: opts.body ? JSON.stringify(opts.body) : undefined }); const data = await response.json(); if (!response.ok) throw new Error(data.message || '操作失败'); return data.data ?? data }
function notify(error) { message.value = error?.message || error; setTimeout(() => message.value = '', 3500) }
async function refresh() { try { products.value = await api('/products'); if (token.value) { me.value = await api('/me'); [orders.value, addresses.value, transactions.value, team.value] = await Promise.all(['/orders','/addresses','/transactions','/team'].map(x => api(x))); unreadCount.value = (await api('/orders/unread-count')).count; addressId.value = addresses.value[0]?.id || '' } } catch(e) { notify(e) } }
async function refreshNotices() { if (!token.value) return; try { const [list, unread] = await Promise.all([api('/orders'), api('/orders/unread-count')]); orders.value = list; unreadCount.value = unread.count } catch { /* 后台暂不可用时保留上次状态，下次重试 */ } }
async function readNotice(order) { if (Number(order.notice_read)) return; try { await api('/orders/'+order.id+'/read',{method:'PUT'}); order.notice_read=1; unreadCount.value=(await api('/orders/unread-count')).count } catch(e) { notify(e) } }
async function login() { try { const result = await api('/auth/' + mode.value, { method:'POST', body:form.value }); token.value = result.token; localStorage.setItem('cym-token', token.value); await refresh(); tab.value = 'shop' } catch(e) { notify(e) } }
function logout() { localStorage.removeItem('cym-token'); token.value=''; me.value=null; unreadCount.value=0; tab.value='shop' }
function openTab(value) { if (value !== 'shop' && !token.value) { tab.value='login'; return } tab.value=value; if (value === 'team') makeQr() }
async function makeQr() { if (!me.value?.invite_code) return; const link = `${location.origin}/#/login?transfer_invite=${me.value.invite_code}`; qr.value = await QRCode.toDataURL(link, { width: 220, margin: 1 }) }
async function copyInvite() { const link = `${location.origin}/#/login?transfer_invite=${me.value.invite_code}`; try { await navigator.clipboard.writeText(link); notify('邀请链接已复制') } catch { window.prompt('复制邀请链接', link) } }
async function saveAddress() { try { await api('/addresses'+(address.value.id?'/'+address.value.id:''), {method:address.value.id?'PUT':'POST',body:address.value}); notify('地址已保存'); address.value={contact_name:'',contact_phone:'',province:'',city:'',district:'',detail:''}; await refresh() } catch(e) { notify(e) } }
async function purchase() { if(busy.value)return; busy.value=true; try { await api('/purchases',{method:'POST',body:{product_id:selected.value.id,address_id:Number(addressId.value),variant:variant.value,request_id:purchaseId.value}}); purchaseId.value=crypto.randomUUID(); selected.value=null; notify('购买成功'); await refresh(); tab.value='orders' } catch(e) { notify(e) } finally { busy.value=false } }
async function send() { if(busy.value)return; busy.value=true; try { await api('/transfer',{method:'POST',body:{...transfer.value,request_id:transferId.value}}); transferId.value=crypto.randomUUID(); transfer.value={phone:'',amount:'',password:''}; notify('转赠成功'); await refresh() } catch(e) { notify(e) } finally { busy.value=false } }
async function changeName() { const username = prompt('新用户名', me.value?.username); if (!username) return; try { await api('/account',{method:'PUT',body:{username}}); await refresh(); notify('用户名已修改') } catch(e) { notify(e) } }
async function changePassword() { const old_password = prompt('请输入原密码'); if (!old_password) return; const new_password = prompt('请输入新密码'); if (!new_password) return; try { await api('/account',{method:'PUT',body:{old_password,new_password}}); notify('密码已修改') } catch(e) { notify(e) } }
async function deleteAddress(id) { if (!confirm('删除此地址？')) return; try { await api('/addresses/'+id,{method:'DELETE'}); await refresh(); notify('地址已删除') } catch(e) { notify(e) } }
function options(p) { try { return typeof p.options === 'string' ? JSON.parse(p.options) : (p.options || []) } catch { return [] } }
function detailImages(p) { try { return typeof p.detail_images === 'string' ? JSON.parse(p.detail_images) : (p.detail_images || []) } catch { return [] } }
let noticeTimer
onMounted(() => { refresh(); noticeTimer=setInterval(refreshNotices, 30000) })
onUnmounted(() => clearInterval(noticeTimer))
</script>
<template>
  <div class="app"><div v-if="message" class="toast">{{ message }}</div>
    <header class="top"><div><small>LOCAL COMMERCE</small><h1>本地商圈</h1></div><button class="top-btn" @click="openTab('profile')">{{ me ? me.username : '登录 / 注册' }}</button></header>
    <main>
      <template v-if="tab === 'shop'"><section class="hero"><div><span>品质生活 · 智慧商圈</span><h2>发现身边的好物</h2><p>精选商品，分享美好生活</p></div><div class="hero-icon">✦</div></section><div class="section-title"><div><h2>商圈精选</h2><p>用产品券兑换心仪好物</p></div><span>{{ products.length }} 件商品</span></div><div class="grid"><article class="product" v-for="p in products" :key="p.id" @click="selected=p; variant='' "><img v-if="p.image" :src="p.image" :alt="p.name"><div v-else class="product-placeholder">✿</div><div class="product-body"><b>{{ p.name }}</b><p>{{ p.description || '精选品质好物' }}</p><strong>{{ p.cost }} <small>产品券</small></strong><div class="product-foot"><span>收益 {{ p.reward }} 券</span><span>库存 {{ p.stock }}</span></div></div></article></div><div v-if="!products.length" class="empty">暂无商品，敬请期待</div></template>
      <template v-if="tab === 'login'"><section class="card form"><h2>{{ mode==='login'?'欢迎回来':'加入本地商圈' }}</h2><p> {{ mode==='login'?'登录后查看您的商圈':'使用推荐人的邀请码注册' }}</p><input v-model="form.phone" placeholder="手机号" type="tel"><input v-if="mode==='register'" v-model="form.username" placeholder="用户名"><input v-model="form.password" placeholder="密码" type="password"><input v-if="mode==='register'" v-model="form.invite_code" placeholder="商圈邀请码"><button class="primary" @click="login">{{ mode==='login'?'登录':'注册' }}</button><button class="link" @click="mode=mode==='login'?'register':'login'">{{ mode==='login'?'没有账号？立即注册':'已有账号？返回登录' }}</button></section></template>
      <template v-if="tab === 'team'"><section class="card team-hero"><small>我的智慧商圈</small><h2>{{ team.reduce((n,x)=>n+Number(x.count),0) }} <small>位成员</small></h2><p>已拓展 {{ team.length }} 个成员分组 · 我的复购 {{ me?.purchase_count ?? 0 }} 次</p></section><section class="card"><h3>邀请新成员</h3><p>专属邀请码 <b>{{ me?.invite_code || '不可邀请' }}</b></p><img v-if="qr" class="qr" :src="qr" alt="商圈邀请二维码"><button v-if="qr" class="outline" @click="copyInvite">复制邀请链接</button></section><section class="card"><h3>成员分组</h3><div v-for="row in team" :key="row.depth" class="list-row"><span>第 {{ row.depth }} 组</span><b>{{ row.count }} 人</b></div><p v-if="!team.length" class="muted">暂无成员</p></section></template>
      <template v-if="tab === 'orders'"><h2>我的订单</h2><article v-for="o in orders" :key="o.id" class="card order"><div class="list-row"><b>{{ o.product_name }}</b><span class="badge">已完成</span></div><p>订单号 {{ o.order_no }}</p><p>购买 {{ o.cost }} 券 · 第 {{ o.purchase_sequence }} 次</p><p v-if="o.variant">款式：{{ o.variant }}</p><button v-if="o.pickup_code" class="notice" @click="readNotice(o)"><span v-if="isUnreadNotice(o)" class="notice-dot" aria-label="未读"></span>到货提醒：提货码 {{ o.pickup_code }} {{ o.pickup_message }}</button></article><div v-if="!orders.length" class="empty">暂无订单</div></template>
      <template v-if="tab === 'profile'"><section class="card profile"><small>我的账户</small><h2>{{ me?.username }}</h2><p>{{ me?.phone }}</p><div class="balance"><span>产品券余额</span><strong>{{ me?.balance }}</strong><small>复购 {{ me?.purchase_count }} 次</small></div></section><div class="actions"><button @click="tab='transfer'">产品券转赠 <span>›</span></button><button @click="tab='addresses'">收货地址 <span>›</span></button><button @click="tab='records'">产品券明细 <span>›</span></button><button @click="changeName">修改用户名 <span>›</span></button><button @click="changePassword">修改密码 <span>›</span></button><button @click="logout">退出登录 <span>›</span></button></div></template>
      <template v-if="tab === 'transfer'"><section class="card form"><h2>产品券转赠</h2><p>余额 {{ me?.balance }} 产品券，按整数原额转赠</p><input v-model="transfer.phone" placeholder="收款人手机号" type="tel"><input v-model="transfer.amount" placeholder="转赠数量" type="number"><input v-model="transfer.password" placeholder="登录密码" type="password"><button class="primary" @click="send">确认转赠</button><button class="link" @click="tab='profile'">返回</button></section></template>
      <template v-if="tab === 'addresses'"><section class="card form"><h2>收货地址</h2><div v-for="a in addresses" :key="a.id" class="address"><b>{{ a.contact_name }} {{ a.contact_phone }}</b><p>{{ a.province }} {{ a.city }} {{ a.district }} {{ a.detail }}</p><button class="link" @click="address={...a}">编辑</button><button class="link" @click="deleteAddress(a.id)">删除</button></div><h3>{{ address.id?'编辑地址':'新增默认地址' }}</h3><input v-model="address.contact_name" placeholder="收货人"><input v-model="address.contact_phone" placeholder="手机号"><div class="columns"><input v-model="address.province" placeholder="省"><input v-model="address.city" placeholder="市"><input v-model="address.district" placeholder="区"></div><input v-model="address.detail" placeholder="详细地址"><button class="primary" @click="saveAddress">保存地址</button><button class="link" @click="tab='profile'">返回</button></section></template>
      <template v-if="tab === 'records'"><section class="card"><h2>产品券明细</h2><div v-for="item in transactions" :key="item.id" class="list-row"><div><b>{{ item.description }}</b><p>{{ item.created_at?.slice(0,10) }}</p></div><strong>{{ item.amount }}</strong></div><p v-if="!transactions.length" class="muted">暂无记录</p><button class="link" @click="tab='profile'">返回</button></section></template>
    </main><nav class="bottom"><button @click="openTab('shop')" :class="{active:tab==='shop'}">⌂<small>商圈</small></button><button @click="openTab('team')" :class="{active:tab==='team'}">♧<small>团队</small></button><button @click="openTab('orders')" :class="{active:tab==='orders'}"><span class="nav-icon">▤<i v-if="unreadCount" class="nav-dot" :aria-label="`${unreadCount}条未读到货提醒`"></i></span><small>订单</small></button><button @click="openTab('profile')" :class="{active:tab==='profile'}">◉<small>我的</small></button></nav>
    <div v-if="selected" class="overlay" @click.self="selected=null"><div class="sheet"><button class="close" @click="selected=null">×</button><img v-if="selected.image" class="detail-img" :src="selected.image"><h2>{{ selected.name }}</h2><p>{{ selected.description }}</p><h3>{{ selected.cost }} 产品券</h3><p>固定收益 {{ selected.reward }} 券 · 库存 {{ selected.stock }}</p><select v-if="options(selected).length" v-model="variant"><option value="">请选择款式</option><option v-for="o in options(selected)" :key="o.id" :value="o.id">{{ o.label }}</option></select><select v-model="addressId"><option value="">请选择收货地址</option><option v-for="a in addresses" :key="a.id" :value="a.id">{{ a.contact_name }} {{ a.detail }}</option></select><button class="link" @click="selected=null;openTab('addresses')">管理收货地址</button><button class="primary" :disabled="busy" @click="token ? purchase() : (selected=null,tab='login')">{{ token ? '确认购买' : '登录后购买' }}</button><img v-for="url in detailImages(selected)" :key="url" class="detail-img" :src="url" alt="商品详情"></div></div>
  </div>
</template>
